def dedupe(items):
    seen = set()
    result = []
    for item in items:
        try:
            if item in seen:
                continue
            seen.add(item)
            result.append(item)
        except TypeError:
            # Unhashable item – use a list to track seen items
            if any(item == s for s in seen):
                continue
            seen.append(item)
            result.append(item)
    return result

