def deep_get(obj, path, default=None):
    """
    Retrieve a value from a nested structure using a dotted path.
    Path components that are digits are treated as list indices.
    Returns `default` if any step is missing.
    """
    for key in path.split('.'):
        if isinstance(obj, dict):
            obj = obj.get(key, default)
        elif isinstance(obj, list):
            if key.isdigit():
                idx = int(key)
                if 0 <= idx < len(obj):
                    obj = obj[idx]
                else:
                    return default
            else:
                return default
        else:
            return default
        if obj is default:
            return default
    return obj
```

