def human_bytes(n):
    if n < 0:
        raise ValueError("n must be non‑negative")
    units = ['B', 'KiB', 'MiB', 'GiB', 'TiB']
    for i, unit in enumerate(units):
        if n < 1024 ** (i + 1):
            if unit == 'B':
                return f"{n} {unit}"
            else:
                return f"{n / 1024 ** i:.1f} {unit}"
    # Fallback (should never be reached)
    return f"{n / 1024 ** 4:.1f} TiB"

