def mask_secrets(text):
    import re
    def repl(match):
        key = match.group(1)
        if any(s in key.lower() for s in ('password', 'token', 'key')):
            return f"{key}=***"
        return match.group(0)
    return re.sub(r'(\b\w*[keytoken]\w*\b)=([^ ]+)', repl, text)

