import hashlib
import json

def stable_hash(obj):
    """
    Return a stable hex hash for nested dict/list/str/int structures.
    The hash is independent of dict key insertion order.
    """
    def _hash(o):
        if isinstance(o, dict):
            # Sort items by key to ensure order‑independent hashing
            return tuple((k, _hash(v)) for k, v in sorted(o.items()))
        elif isinstance(o, list):
            return tuple(_hash(item) for item in o)
        elif isinstance(o, (str, int)):
            return o
        else:
            raise TypeError(f"Unsupported type: {type(o)}")

    canonical = _hash(obj)
    serialized = json.dumps(canonical, separators=(',', ':'))
    return hashlib.sha256(serialized.encode('utf-8')).hexdigest()
```

